-- Sandbox catch-up batch 10 (#6356): additive indexes, constraints and triggers copied from production.
-- Also the forward fix for batch 9: app.handle_new_auth_user() ACL on sandbox already equals production
-- (execute for PUBLIC and service_role); this batch asserts no grant/revoke on it, so nothing contradictory remains.
create unique index if not exists app_comment_poppim_client_operation_uq ON app.comment USING btree (created_by_profile_id, source_id) WHERE ((source_system = 'poppim-web-comment'::text) AND (source_id IS NOT NULL));
create unique index if not exists character_id_licensor_id_key ON core.character USING btree (id, licensor_id);
create unique index if not exists factory_designflow_vendor_id_key ON core.factory USING btree (designflow_vendor_id) WHERE (designflow_vendor_id IS NOT NULL);
create index if not exists sync_run_source_name_source_system_status_started_at_idx ON ingest.sync_run USING btree (source_name, source_system, status, started_at DESC);
create index if not exists sku_sg_dcp_asset_file_idx ON plm.dcp_asset USING btree (sku_sg_file_key);
create index if not exists sku_sg_dcp_style_guide_label_idx ON plm.dcp_style_guide USING btree (NULLIF(sku_sg_label_key, ''::text));
create index if not exists sku_sg_dcp_style_guide_pending_idx ON plm.dcp_style_guide USING btree (sku_sg_label_key) WHERE (sku_sg_label_key IS NULL);
create index if not exists item_item_number_idx ON plm.item USING btree (item_number);
create index if not exists sku_sg_lucasfilm_dcp_asset_file_idx ON plm.lucasfilm_dcp_asset USING btree (sku_sg_file_key);
create index if not exists sku_sg_lucasfilm_dcp_style_guide_label_idx ON plm.lucasfilm_dcp_style_guide USING btree (NULLIF(sku_sg_label_key, ''::text));
create index if not exists sku_sg_lucasfilm_dcp_style_guide_pending_idx ON plm.lucasfilm_dcp_style_guide USING btree (sku_sg_label_key) WHERE (sku_sg_label_key IS NULL);
create index if not exists sku_sg_marvel_asgard_node_asset_observation_file_idx ON plm.marvel_asgard_node_asset_observation USING btree (sku_sg_file_key);
create index if not exists sku_sg_marvel_asgard_style_guide_label_idx ON plm.marvel_asgard_style_guide USING btree (NULLIF(sku_sg_label_key, ''::text));
create index if not exists sku_sg_marvel_asgard_style_guide_pending_idx ON plm.marvel_asgard_style_guide USING btree (sku_sg_label_key) WHERE (sku_sg_label_key IS NULL);
create index if not exists sku_sg_marvel_dcp_asset_file_idx ON plm.marvel_dcp_asset USING btree (sku_sg_file_key);
create index if not exists sku_sg_marvel_dcp_style_guide_label_idx ON plm.marvel_dcp_style_guide USING btree (NULLIF(sku_sg_label_key, ''::text));
create index if not exists sku_sg_marvel_dcp_style_guide_pending_idx ON plm.marvel_dcp_style_guide USING btree (sku_sg_label_key) WHERE (sku_sg_label_key IS NULL);
create index if not exists sku_sg_nbcu_asset_file_idx ON plm.nbcu_asset USING btree (sku_sg_file_key);
create index if not exists sku_sg_nbcu_asset_snapshot_idx ON plm.nbcu_asset USING btree (capture_id, asset_source_key) INCLUDE (file_name, sku_sg_file_key);
create index if not exists sku_sg_nbcu_style_guide_label_idx ON plm.nbcu_style_guide USING btree (NULLIF(sku_sg_label_key, ''::text));
create index if not exists sku_sg_nbcu_style_guide_pending_idx ON plm.nbcu_style_guide USING btree (sku_sg_label_key) WHERE (sku_sg_label_key IS NULL);
create index if not exists opa_compliance_membership_capture_idx ON plm.opa_property_scope_membership USING btree (compliance_capture_id, licensed_property_id);
create index if not exists sku_sg_peanuts_asset_file_idx ON plm.peanuts_asset USING btree (sku_sg_file_key);
create index if not exists sku_sg_peanuts_style_guide_label_idx ON plm.peanuts_style_guide USING btree (NULLIF(sku_sg_label_key, ''::text));
create index if not exists sku_sg_peanuts_style_guide_pending_idx ON plm.peanuts_style_guide USING btree (sku_sg_label_key) WHERE (sku_sg_label_key IS NULL);
create index if not exists sku_sg_sesame_asset_file_idx ON plm.sesame_asset USING btree (sku_sg_file_key);
create index if not exists sku_sg_sesame_style_guide_label_idx ON plm.sesame_style_guide USING btree (NULLIF(sku_sg_label_key, ''::text));
create index if not exists sku_sg_sesame_style_guide_pending_idx ON plm.sesame_style_guide USING btree (sku_sg_label_key) WHERE (sku_sg_label_key IS NULL);
create index if not exists source_resolution_open_status_idx ON plm.source_resolution USING btree (resolution_status) WHERE (resolution_status = ANY (ARRAY['unresolved'::text, 'ambiguous'::text, 'deferred'::text]));
create index if not exists sku_sg_wb_asset_normalized_file_idx ON plm.wb_asset_normalized USING btree (sku_sg_file_key);
create index if not exists sku_sg_wb_asset_snapshot_idx ON plm.wb_asset_normalized USING btree (id) INCLUDE (file_name, sku_sg_file_key);
create index if not exists plm_wb_character_normalized_unresolved_idx ON plm.wb_character_normalized USING btree (resolution_status) WHERE (resolution_status <> 'resolved'::text);
create index if not exists sku_sg_wb_style_guide_normalized_label_idx ON plm.wb_style_guide_normalized USING btree (NULLIF(sku_sg_label_key, ''::text));
create index if not exists sku_sg_wb_style_guide_normalized_pending_idx ON plm.wb_style_guide_normalized USING btree (sku_sg_label_key) WHERE (sku_sg_label_key IS NULL);
create index if not exists plm_wildbrain_character_unresolved_idx ON plm.wildbrain_character USING btree (resolution_status) WHERE (resolution_status <> 'resolved'::text);
alter table core.factory add constraint factory_orders_completed_check CHECK ((orders_completed >= 0));
alter table core.factory add constraint factory_orders_with_problem_check CHECK ((orders_with_problem >= 0));
alter table core.factory add constraint factory_party_type_check CHECK ((party_type = ANY (ARRAY['factory'::text, 'trading_company'::text, 'both'::text])));
alter table plm.dcp_opa_property_resolution add constraint dcp_opa_property_resolution_creative_state_ck CHECK (((creative_decision_state IS NULL) OR ((creative_decision_state = ANY (ARRAY['mapped'::text, 'unmapped'::text, 'conflict'::text, 'excluded'::text])) AND (approval_status = 'approved'::text))));
alter table plm.dcp_opa_property_resolution_member add constraint dcp_opa_property_resolution_member_identity_ck CHECK (((btrim(submission_source_system) <> ''::text) AND (btrim(submission_source_table) <> ''::text) AND (btrim(submission_source_id) <> ''::text)));
alter table plm.dcp_opa_property_resolution_member add constraint dcp_opa_property_resolution_member_ne_licensed_property_id_fkey FOREIGN KEY (licensed_property_id) REFERENCES plm.opa_property(licensed_property_id) ON DELETE RESTRICT;
alter table plm.dcp_opa_property_resolution_member add constraint dcp_opa_property_resolution_member_new_resolution_id_fkey FOREIGN KEY (resolution_id) REFERENCES plm.dcp_opa_property_resolution(resolution_id) ON DELETE RESTRICT;
alter table plm.dcp_opa_property_resolution_member add constraint dcp_opa_property_resolution_member_opa_ck CHECK ((((submission_source_table = 'plm.opa_property'::text) = (licensed_property_id IS NOT NULL)) AND ((licensed_property_id IS NULL) OR (submission_source_id = (licensed_property_id)::text))));
alter table plm.item add constraint item_product_type_status_check CHECK ((product_type_status = ANY (ARRAY['accepted'::text, 'unreadable'::text, 'placeholder'::text])));
alter table plm.lucasfilm_dcp_asset add constraint lucasfilm_dcp_asset_do_not_use_reason_chk CHECK (((do_not_use_reason IS NULL) OR (do_not_use_reason ~ '[^[:space:]]'::text)));
alter table plm.marvel_dcp_asset add constraint marvel_dcp_asset_do_not_use_reason_chk CHECK (((do_not_use_reason IS NULL) OR (do_not_use_reason ~ '[^[:space:]]'::text)));
alter table plm.nbcu_character add constraint nbcu_character_core_character_id_fkey FOREIGN KEY (core_character_id) REFERENCES core.character(id) ON UPDATE CASCADE ON DELETE RESTRICT;
alter table plm.opa_character add constraint opa_character_core_character_id_fkey FOREIGN KEY (core_character_id) REFERENCES core.character(id) ON UPDATE CASCADE ON DELETE RESTRICT;
alter table plm.opa_property_scope_membership add constraint opa_compliance_membership_capture_fk FOREIGN KEY (compliance_capture_id) REFERENCES plm.opa_property_compliance_capture(compliance_capture_id) ON DELETE RESTRICT;
alter table plm.opa_property_scope_membership add constraint opa_compliance_membership_shape_ck CHECK ((((compliance_capture_id IS NULL) AND (compliance_status = 'unknown'::text)) OR ((compliance_capture_id IS NOT NULL) AND (compliance_status = ANY (ARRAY['compliant'::text, 'non_compliant'::text])))));
alter table plm.opa_property_scope_membership add constraint opa_compliance_membership_status_ck CHECK ((compliance_status = ANY (ARRAY['compliant'::text, 'non_compliant'::text, 'unknown'::text])));
alter table plm.pmt_character add constraint pmt_character_core_character_id_fkey FOREIGN KEY (core_character_id) REFERENCES core.character(id) ON UPDATE CASCADE ON DELETE RESTRICT;
alter table plm.twentieth_century_dcp_asset add constraint twentieth_century_dcp_asset_do_not_use_reason_chk CHECK (((do_not_use_reason IS NULL) OR (do_not_use_reason ~ '[^[:space:]]'::text)));
alter table plm.wb_character_normalized add constraint plm_wb_character_normalized_core_character_fk FOREIGN KEY (core_character_id) REFERENCES core.character(id) ON DELETE RESTRICT;
alter table plm.wb_character_normalized add constraint plm_wb_character_normalized_resolution_ck CHECK ((((resolution_status = 'resolved'::text) AND (core_character_id IS NOT NULL) AND (resolved_at IS NOT NULL) AND (resolved_by IS NOT NULL) AND (btrim(resolved_by) <> ''::text)) OR ((resolution_status <> 'resolved'::text) AND (core_character_id IS NULL) AND (resolved_at IS NULL) AND (resolved_by IS NULL))));
alter table plm.wb_character_normalized add constraint plm_wb_character_normalized_resolution_status_ck CHECK ((resolution_status = ANY (ARRAY['unresolved'::text, 'resolved'::text, 'ambiguous'::text, 'not_a_character'::text])));
alter table plm.wildbrain_character add constraint plm_wildbrain_character_core_character_fk FOREIGN KEY (core_character_id) REFERENCES core.character(id) ON DELETE RESTRICT;
alter table plm.wildbrain_character add constraint plm_wildbrain_character_resolution_ck CHECK ((((resolution_status = 'resolved'::text) AND (core_character_id IS NOT NULL) AND (resolved_at IS NOT NULL) AND (resolved_by IS NOT NULL) AND (btrim(resolved_by) <> ''::text)) OR ((resolution_status <> 'resolved'::text) AND (core_character_id IS NULL) AND (resolved_at IS NULL) AND (resolved_by IS NULL))));
alter table plm.wildbrain_character add constraint plm_wildbrain_character_resolution_status_ck CHECK ((resolution_status = ANY (ARRAY['unresolved'::text, 'resolved'::text, 'ambiguous'::text, 'not_a_character'::text])));
CREATE TRIGGER app_comment_body_revision BEFORE INSERT OR UPDATE ON app.comment FOR EACH ROW EXECUTE FUNCTION app.comment_body_revision_trg_fn();
CREATE TRIGGER pm_jev_source_changed AFTER UPDATE OF body ON app.comment FOR EACH ROW EXECUTE FUNCTION pim.pm_jev_source_changed_trg_fn();
CREATE TRIGGER redirect_retired_wb_licensor BEFORE INSERT OR UPDATE OF licensor_id ON plm.licensor_import FOR EACH ROW EXECUTE FUNCTION plm.redirect_retired_wb_licensor();
CREATE TRIGGER opa_compliance_membership_guard BEFORE INSERT OR DELETE OR UPDATE ON plm.opa_property_scope_membership FOR EACH ROW EXECUTE FUNCTION plm.guard_opa_property_compliance_membership();
CREATE TRIGGER opa_compliance_membership_truncate_guard BEFORE TRUNCATE ON plm.opa_property_scope_membership FOR EACH STATEMENT EXECUTE FUNCTION plm.guard_opa_property_compliance_membership();
CREATE TRIGGER production_po_no_reuse BEFORE INSERT OR UPDATE ON plm.production_order FOR EACH ROW EXECUTE FUNCTION plm.guard_production_po_number();
CREATE TRIGGER redirect_retired_wb_licensor BEFORE INSERT OR UPDATE OF licensor_id ON plm.property_import FOR EACH ROW EXECUTE FUNCTION plm.redirect_retired_wb_licensor();
